"use client";
import { useState } from "react";import { api,uuidv7 } from "../../lib/api";
export default function Schedule(){const [dataset,setDataset]=useState(""),[message,setMessage]=useState("Paste a dataset version ID to generate a timetable.");async function generate(){const r=await api<{jobId:string}>("/api/v1/schedules/generate",{method:"POST",headers:{"idempotency-key":uuidv7()},body:JSON.stringify({datasetVersionId:dataset})});setMessage(r.data?`Generation queued: ${r.data.jobId}`:r.error??"Failed")}return <main className="route"><p className="eyebrow">SCHEDULER</p><h1>Generate a conflict-free timetable</h1><p>Generation runs in a worker and must pass the official validator before approval.</p><input placeholder="Dataset version UUID" value={dataset} onChange={e=>setDataset(e.target.value)}/><button className="primary" onClick={generate}>Generate timetable</button><p className="status">{message}</p></main>}
